1: import useSWR from 'swr';
2: import { fhirBaseUrl, openmrsFetch, restBaseUrl, type OpenmrsResource } from '@openmrs/esm-framework';
3: import {
4:   type Allergy,
5:   type FHIRAllergy,
6:   type FHIRAllergyResponse,
7:   type PatientAllergyPayload,
8:   type UseAllergies,
9: } from '../types';
10: 
11: export function useAllergies(patientUuid: string): UseAllergies {
12:   const allergiesUrl = `${fhirBaseUrl}/AllergyIntolerance?patient=${patientUuid}`;
13: 
14:   const { data, error, isLoading, isValidating, mutate } = useSWR<{ data: FHIRAllergyResponse }, Error>(
15:     patientUuid ? allergiesUrl : null,
16:     openmrsFetch,
17:   );
18: 
19:   const formattedAllergies =
20:     data?.data?.total > 0
21:       ? data?.data.entry
22:           .map((entry) => entry.resource ?? [])
23:           .map(mapAllergyProperties)
24:           .sort((a, b) => (b.lastUpdated > a.lastUpdated ? 1 : -1))
25:       : null;
26: 
27:   return {
28:     allergies: data ? formattedAllergies : null,
29:     error,
30:     isLoading,
31:     isValidating,
32:     mutate,
33:   };
34: }
35: 
36: function mapAllergyProperties(allergy: FHIRAllergy): Allergy {
37:   const manifestations = allergy?.reaction[0]?.manifestation?.map((coding) => coding?.text);
38:   return {
39:     id: allergy?.id,
40:     clinicalStatus: allergy?.clinicalStatus?.coding[0]?.display,
41:     criticality: allergy?.criticality,
42:     display: allergy?.code?.text ?? allergy?.code?.coding[0]?.display,
43:     recordedDate: allergy?.recordedDate,
44:     recordedBy: allergy?.recorder?.display,
45:     recorderType: allergy?.recorder?.type,
46:     note: allergy?.note?.[0]?.text,
47:     reactionToSubstance: allergy?.reaction[0]?.substance?.text,
48:     reactionManifestations: manifestations,
49:     reactionSeverity: allergy?.reaction[0]?.severity,
50:     lastUpdated: allergy?.meta?.lastUpdated,
51:   };
52: }
53: 
54: export function saveAllergy(
55:   patientAllergy: PatientAllergyPayload,
56:   patientUuid: string,
57:   abortController: AbortController,
58: ) {
59:   const reactions = patientAllergy.reactionUuids.map((reaction: OpenmrsResource) => {
60:     return {
61:       reaction: {
62:         uuid: reaction.uuid,
63:       },
64:     };
65:   });
66: 
67:   return openmrsFetch(`${restBaseUrl}/patient/${patientUuid}/allergy`, {
68:     headers: {
69:       'Content-Type': 'application/json',
70:     },
71:     method: 'POST',
72:     body: {
73:       allergen: {
74:         allergenType: patientAllergy?.allergenType,
75:         codedAllergen: {
76:           uuid: patientAllergy?.codedAllergenUuid,
77:         },
