11: export function useAllergies(patientUuid: string): UseAllergies {
12:   const allergiesUrl = `${fhirBaseUrl}/AllergyIntolerance?patient=${patientUuid}`;
13: 
14:   const { data, error, isLoading, isValidating, mutate } = useSWR<{ data: FHIRAllergyResponse }, Error>(
15:     patientUuid ? allergiesUrl : null,
16:     openmrsFetch,
17:   );
18: 
19:   const formattedAllergies =
20:     data?.data?.total > 0
21:       ? data?.data.entry
22:           .map((entry) => entry.resource ?? [])
23:           .map(mapAllergyProperties)
24:           .sort((a, b) => (b.lastUpdated > a.lastUpdated ? 1 : -1))
25:       : null;
26: 
27:   return {
28:     allergies: data ? formattedAllergies : null,
29:     error,
30:     isLoading,
31:     isValidating,
32:     mutate,
33:   };
